import { execSync } from "node:child_process";
import * as path from "node:path";
const DISABLE_AUTO_FETCH_TOKEN_ENV = "DISABLE_AUTO_FETCH_TOKEN";
function getYaExecutable() {
    try {
        execSync("which ya", {
            encoding: "utf-8",
            timeout: 3000,
            stdio: "ignore",
        });
        return "ya";
    }
    catch {
        const arcadia = process.env.ARCADIA;
        return arcadia ? path.join(arcadia, "ya") : "ya";
    }
}
function isAutoFetchTokenDisabled(env) {
    return env[DISABLE_AUTO_FETCH_TOKEN_ENV]?.trim().toLowerCase() === "true";
}
function exitMissingToken(autoFetchAttempted) {
    if (autoFetchAttempted) {
        console.error(`Error: token required. Set ELIZA_API_KEY env var or ensure 'ya tool fetch-token' works (uses SSH/skotty). To disable auto-fetch, set ${DISABLE_AUTO_FETCH_TOKEN_ENV}=true.`);
    }
    else {
        console.error(`Error: token required. Set ELIZA_API_KEY env var. Auto-fetch is disabled by ${DISABLE_AUTO_FETCH_TOKEN_ENV}=true.`);
    }
    process.exit(1);
}
export function resolveElizaToken() {
    const env = process.env;
    const token = env.ELIZA_API_KEY;
    if (token) {
        return token;
    }
    if (isAutoFetchTokenDisabled(env)) {
        exitMissingToken(false);
    }
    try {
        return execSync(`${getYaExecutable()} tool fetch-token -preset eliza`, {
            encoding: "utf-8",
            timeout: 15_000,
        }).trim();
    }
    catch {
        exitMissingToken(true);
    }
}
